<script setup>
import RecycleBin from "./RecycleBin.vue";
import {useUiText} from "../ui-text";
const ui=useUiText();

import {fuzzyMatch} from '../../shared/search.mjs';
import {ref,computed,watch} from 'vue';
import {Search,Upload,Images,Download,Paintbrush,X,SlidersHorizontal,ChevronLeft,ChevronRight,RefreshCw,Trash2,ListChecks,RotateCcw} from 'lucide-vue-next';
import {imageEditingMode} from '../../shared/panel-generation.mjs';
import {useStudio,clone,api} from '../store';
const refreshing=ref(false);async function refresh(){refreshing.value=true;try{await s.refreshCollections();s.notify('画廊已刷新');}finally{refreshing.value=false;}}
const s=useStudio(),search=ref(''),filter=ref('all'),detail=ref(null),input=ref(),page=ref(0);const desktop=!!window.desktop;
if(s.config.galleryPrefs){search.value=s.config.galleryPrefs.search||'';filter.value=s.config.galleryPrefs.filter||'all';page.value=s.config.galleryPrefs.page||0;}
watch([search,filter,page],()=>{s.config.galleryPrefs={search:search.value,filter:filter.value,page:page.value};});
const filtered=computed(()=>s.gallery.filter(item=>(filter.value==='all'||(filter.value==='generated'?!item.imported:item.imported))&&fuzzyMatch(search.value,item.title,item.params?.positive,item.created,new Date(item.created).toLocaleString())));
const visible=computed(()=>filtered.value.slice(page.value*40,(page.value+1)*40));
const selecting=ref(false),selected=ref([]),pendingDelete=ref(null),deleting=ref(false),trashOpen=ref(false),trash=ref([]),restoring=ref(false);
watch(()=>s.gallery.map(item=>item.id),ids=>{selected.value=selected.value.filter(id=>ids.includes(id));if(detail.value&&!ids.includes(detail.value.id))detail.value=null;page.value=Math.min(page.value,Math.max(0,Math.ceil(filtered.value.length/40)-1));});
function toggle(id){selected.value=selected.value.includes(id)?selected.value.filter(value=>value!==id):[...selected.value,id];}
const pageSelected=computed(()=>visible.value.length>0&&visible.value.every(item=>selected.value.includes(item.id)));
function selectPage(){const ids=new Set(visible.value.map(item=>item.id));selected.value=pageSelected.value?selected.value.filter(id=>!ids.has(id)):[...new Set([...selected.value,...ids])];}
function toggleSelection(){selecting.value=!selecting.value;selected.value=[];}
async function remove(){deleting.value=true;try{await window.__mogeFlush?.();const result=await api('gallery/delete',{ids:pendingDelete.value});s.gallery=result.gallery;trash.value=result.trash;pendingDelete.value=null;s.notify(`已将 ${result.count} 张图片移入回收区`);}finally{deleting.value=false;}}
async function openTrash(){trash.value=await api('gallery/trash');trashOpen.value=true;}
async function recover(ids){restoring.value=true;try{const result=await api('gallery/restore',{ids});s.gallery=result.gallery;trash.value=result.trash;s.notify(`已恢复 ${result.count} 张图片`);}finally{restoring.value=false;}}
async function importFiles(e){await s.action(()=>s.importImages([...e.target.files]));e.target.value='';}
function edit(item){s.selectedImage=item;s.tab='inpaint';detail.value=null;}
function restore(item){if(!item.params)return;s.config.activeProfile=item.params.type;Object.assign(s.p,clone(item.params));s.selectedImage=item;s.tab=imageEditingMode(item)==='inpaint'?'inpaint':'generate';detail.value=null;s.notify(s.t('已恢复这张图片的生成参数','Generation settings restored'));}
async function download(item){const blob=await(await fetch(item.url)).blob();await s.exportFile(item.title+'.png',blob);}
</script>
<template><div class="gallery-workspace"><div class="gallery-toolbar"><div class="search-input"><Search :size="17"/><input v-model="search" :placeholder="ui(s.t('模糊搜索名称、提示词或日期','Search title, prompt or date'))" @input="page=0"/></div><div class="segmented"><button v-for="(label,key) in {all:s.t('全部','All'),generated:s.t('生成图像','Generated'),imported:s.t('导入图像','Imported')}" :class="{active:filter===key}" @click="filter=key;page=0">{{ui(label)}}</button></div><button class="secondary" :class="{active:selecting}" @click="toggleSelection"><ListChecks :size="16"/>{{ui(selecting?'退出多选':'多选')}}</button><button class="secondary" @click="s.action(openTrash)"><Trash2 :size="16"/>{{ui("回收区")}}</button><span class="muted">{{ui(filtered.length)}} {{ui(s.t('张图片','images'))}}</span><button class="secondary" :disabled="refreshing" :aria-busy="refreshing" @click="s.action(refresh)"><RefreshCw :size="15"/>{{ui(refreshing?'刷新中…':'刷新画廊')}}</button><button class="primary" @click="desktop?s.action(()=>s.importImages()):input.click()"><Upload :size="16"/>{{ui(s.t('导入本地图片','Import images'))}}</button></div>
 <div v-if="selecting" class="gallery-selection-bar"><label><input type="checkbox" :checked="pageSelected" :disabled="!visible.length" @change="selectPage"/>{{ui("全选本页")}}</label><span>{{ui("已选 ")}}{{ui(selected.length)}}{{ui(" 张")}}</span><button class="quiet" :disabled="!selected.length" @click="selected=[]">{{ui("取消选择")}}</button><button class="secondary danger" :disabled="!selected.length" @click="pendingDelete=[...selected]"><Trash2 :size="16"/>{{ui("删除所选")}}</button></div>
 <div v-if="!filtered.length" class="card empty-gallery"><div class="onboard-icon"><Images :size="30"/></div><h2>{{ui(s.t('你的作品，将在这里相遇','Your creations will live here'))}}</h2><p>{{ui(s.t('生成的图片会自动加入画廊。也可以导入已有图片，继续制作漫画。','Generated images appear here automatically. Import your own images to make a comic.'))}}</p><div class="button-row"><button class="primary" @click="s.tab='generate'">{{ui(s.t('生成第一张图片','Generate your first image'))}}</button><button class="secondary" @click="desktop?s.action(()=>s.importImages()):input.click()">{{ui(s.t('导入图片','Import image'))}}</button></div></div>
 <div v-else class="gallery-grid"><article v-for="item in visible" :key="item.id" class="gallery-card" :class="{selected:selected.includes(item.id)}" @click="selecting?toggle(item.id):detail=item"><div class="gallery-image"><label v-if="selecting" class="gallery-select" @click.stop><input type="checkbox" :checked="selected.includes(item.id)" :aria-label="ui('选择图片 '+item.title)" @change="toggle(item.id)"/></label><button class="gallery-delete" :title="ui('删除图片 '+item.title)" :aria-label="ui('删除图片 '+item.title)" @click.stop="pendingDelete=[item.id]"><Trash2 :size="17"/></button><img :src="item.url" :alt="ui(item.title)" loading="lazy"/><span>{{ui(item.imported?s.t('导入','Imported'):item.params?.type==='expanded'?'2.9B':'Anima')}}</span><div class="gallery-image-actions"><button @click.stop="edit(item)" :title="ui(s.t('局部重绘','Inpaint'))"><Paintbrush :size="17"/></button><button @click.stop="download(item)" :title="ui(s.t('保存图片','Save image'))"><Download :size="17"/></button></div></div><div class="gallery-caption"><strong>{{item.title}}</strong><small>{{ui(new Date(item.created).toLocaleString())}}</small></div></article></div>
 <div v-if="filtered.length>40" class="pagination"><button class="secondary" :disabled="page===0" @click="page--"><ChevronLeft :size="16"/>{{ui(s.t('上一页','Previous'))}}</button><span>{{ui(page+1)}} / {{ui(Math.ceil(filtered.length/40))}}</span><button class="secondary" :disabled="(page+1)*40>=filtered.length" @click="page++">{{ui(s.t('下一页','Next'))}}<ChevronRight :size="16"/></button></div>
 <div v-if="pendingDelete" class="modal-backdrop" @click.self="!deleting&&(pendingDelete=null)"><section class="modal gallery-delete-dialog" role="dialog" :aria-label="ui(&quot;删除图片&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :disabled="deleting" :aria-label="ui(&quot;关闭删除确认&quot;)" @click="pendingDelete=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui("删除 ")}}{{ui(pendingDelete.length)}}{{ui(" 张图片？")}}</h2></div><p>{{ui("图片与其提示词、生成参数、遮罩草稿和候选记录会一起移入回收区，可一并恢复。漫画中已使用的图片保留显示。")}}</p><div class="button-row"><button class="secondary" :disabled="deleting" @click="pendingDelete=null">{{ui("取消")}}</button><button class="primary" :disabled="deleting" @click="s.action(remove)"><Trash2 :size="16"/>{{ui(deleting?'正在删除…':'移入回收区')}}</button></div></section></div>
 <RecycleBin v-if="trashOpen" initial="images" @close="trashOpen=false" @changed="s.action(async()=>{trash=await api('gallery/trash');await s.refreshCollections()})"/>
 <input ref="input" type="file" accept="image/png,image/jpeg,image/webp" multiple class="hidden" @change="importFiles"/>
 <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal image-detail"><div class="modal-title modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭图片详情&quot;)" @click="detail=null"><X :size="20"/></button></div><div class="detail-preview" v-preview-zoom><img :src="detail.url"/></div><div class="detail-info"><span class="eyebrow">YOUR CREATION</span><h2>{{detail.title}}</h2><p>{{ui(new Date(detail.created).toLocaleString())}}</p><template v-if="detail.params"><label>{{ui(s.t('正面提示词','Positive prompt'))}}</label><p class="prompt-detail">{{detail.params.positive}}</p><label>{{ui(s.t('负面提示词','Negative prompt'))}}</label><p class="prompt-detail">{{detail.params.negative}}</p><div class="metadata-grid"><span>{{ui(detail.params.width)}} × {{ui(detail.params.height)}}</span><span>Steps {{ui(detail.params.steps)}}</span><span>CFG {{ui(detail.params.cfg)}}</span><span>Seed {{ui(detail.params.seed)}}</span><span>{{ui(detail.params.sampler)}}</span><span>{{ui(detail.params.scheduler)}}</span></div><button class="secondary wide" @click="restore(detail)"><SlidersHorizontal :size="16"/>{{ui(s.t('恢复全部生成参数','Restore all settings'))}}</button></template><p v-else class="info-note">{{ui(s.t('这张图片没有保存生成提示词；局部重绘时请手动补填。','This image has no generation metadata. Add a prompt before inpainting.'))}}</p><button class="primary wide" @click="edit(detail)"><Paintbrush :size="16"/>{{ui(s.t('发送到局部重绘','Open in inpaint'))}}</button><button class="secondary wide" @click="download(detail)"><Download :size="16"/>{{ui(s.t('另存为图片','Save image as'))}}</button></div></section></div>
</div></template>
